%pyspark

# Function to parse an RDD using a specified delimiter
def parse_rdd(rdd, delimiter):
    # Split each record into individual fields
    return rdd.map(lambda x: x.split(delimiter))

# Function to display sample records and total record count
def preview_rdd(rdd, dataset_name):
    print("First 3 Parsed {} Records:".format(dataset_name))
    for record in rdd.take(3):
        print(record)
    print("\nTotal {} Records: {}".format(dataset_name, rdd.count()))

%sh

cqlsh -k movielen -e "

DROP TABLE IF EXISTS average_rating;
CREATE TABLE average_rating (
    movie_id INT PRIMARY KEY,
    average_rating DOUBLE
);

DROP TABLE IF EXISTS top10_movies;
CREATE TABLE top10_movies (
    movie_title TEXT PRIMARY KEY,
    total_ratings INT,
    average_rating DOUBLE
);

DROP TABLE IF EXISTS active_favourite_genre;
CREATE TABLE active_favourite_genre (
    user_id INT PRIMARY KEY,
    total_movies_rated INT,
    favorite_genre TEXT
);

DROP TABLE IF EXISTS young_users;
CREATE TABLE young_users (
    user_id INT PRIMARY KEY,
    age INT,
    gender TEXT,
    occupation TEXT
);

DROP TABLE IF EXISTS scientist_users;
CREATE TABLE scientist_users (
    user_id INT PRIMARY KEY,
    age INT,
    gender TEXT,
    occupation TEXT
);
"

%sh

echo '

use movielen

db.average_rating.insert([
    {movie_id:829, average_rating:2.65},
    {movie_id:1436, average_rating:2.50}
])

db.top10_movies.insert([
    {movie_title:"Cosi (1996)", total_ratings:4, average_rating:4.0},
    {movie_title:"Psycho (1960)", total_ratings:239, average_rating:4.10}
])

db.active_favourite_genre.insert([
    {user_id:405, total_movies_rated:737, favorite_genre:"Drama"},
    {user_id:655, total_movies_rated:685, favorite_genre:"Drama"}
])

db.young_users.insert([
    {user_id:30, age:7, gender:"M", occupation:"student"},
    {user_id:36, age:19, gender:"F", occupation:"student"}
])

db.scientist_users.insert([
    {user_id:107, age:39, gender:"M", occupation:"scientist"},
    {user_id:183, age:33, gender:"M", occupation:"scientist"}
])

' | mongo

